defmodule ArchAstro.SDK.V1.Threads do
  @moduledoc """
  Thread API resource.
  """

  @doc """
  Delete a thread

  Permanently deletes a thread and all of its messages and artifacts. This action
  cannot be undone.

  The authenticated user must own the thread or be an owner of the team the thread
  belongs to. Attempting to delete a thread owned by another user or team returns 403.


  Empty response on successful deletion.
  """
  @spec delete(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, :ok} | {:error, ArchAstro.SDK.Error.reason()}
  def delete(client, thread) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}"
    ArchAstro.SDK.HTTP.request(client, :delete, path, decode: :void)
  end

  @doc """
  Retrieve a thread

  Returns the full thread record for the given thread ID. The authenticated user
  must own the thread or be a member of the workspace it belongs to.

  Use this endpoint to fetch the current state of a single thread, including its
  title, description, and metadata. To list many threads, use the list endpoint
  with cursor-based pagination.


  The requested thread object.
  """
  @spec get(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.Thread.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def get(client, thread) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}"
    ArchAstro.SDK.HTTP.request(client, :get, path, decode: {:ref, ArchAstro.SDK.Types.Thread})
  end

  @doc """
  Update a thread

  Updates one or more mutable properties of the specified thread and returns
  the full thread object with the applied changes. Only the fields you provide
  are modified; omitted fields retain their current values.

  If `profile_picture` is supplied, the image is uploaded before the other
  fields are saved, after all ordinary thread fields have passed validation.
  Supplying invalid base64 picture data returns 422 and no other fields are
  updated.

  Visibility can only widen: `private` may become `restricted` or `team`, and
  `restricted` may become `team`. The authenticated viewer must have
  permission to modify the thread.

  Mirror-thread titles, descriptions, and notification state remain editable
  by privileged app viewers. Mirror metadata, visibility, and membership are
  provider-managed and cannot be changed through this endpoint.


  The thread object after the update has been applied.
  """
  @spec replace(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PutApiV1ThreadsThread.Input.t()
        ) :: {:ok, ArchAstro.SDK.Types.Thread.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def replace(client, thread, input) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}"

    ArchAstro.SDK.HTTP.request(client, :put, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.Thread}
    )
  end

  @doc """
  List agents in a thread

  Returns the agents participating in the specified thread. Only personal user
  threads (threads owned by a single user, not a team) expose agents through
  this endpoint; requests for team threads return 404.

  The authenticated user must have visibility into the thread. Each agent entry
  includes display information such as name and profile picture. Thread-level
  overrides (e.g. a custom name or profile picture set for this thread) take
  precedence over the agent's default values. When the caller is the thread
  owner, each entry also includes an `agent_config` object describing the
  agent's message policy and context configuration.


  Successful response
  """
  @spec agents(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadAgents.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def agents(client, thread) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/agents"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadAgents.Response}
    )
  end

  @doc """
  List artifacts for a thread

  Returns all artifacts produced during a thread's AI conversation. Artifacts are
  structured outputs such as code files, documents, or generated assets created
  by the AI agent in response to messages in the thread.

  The authenticated user must have access to the specified thread. Results are
  returned in a single page; there is no cursor-based pagination for this endpoint.


  Successful response
  """
  @spec artifacts(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadArtifacts.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def artifacts(client, thread) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/artifacts"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadArtifacts.Response}
    )
  end

  @doc """
  Mark a thread as read

  Records that a user has read up to a specific message in the thread. Unread
  indicators and badge counts are cleared up to the specified message.

  You must supply exactly one of `last_read_message` or `use_latest_message`.
  Omitting both returns 400. If `use_latest_message` is `true` and the thread
  has no messages, the request succeeds silently with no state change.

  For server-to-server (S2S) requests where no user identity is present in the
  token, the `user` param is required to identify whose read state to update.


  Empty response on success.
  """
  @spec mark_read(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PostApiV1ThreadsThreadMarkRead.Input.t()
        ) :: {:ok, :ok} | {:error, ArchAstro.SDK.Error.reason()}
  def mark_read(client, thread, input) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/mark_read"
    ArchAstro.SDK.HTTP.request(client, :post, path, body: input, decode: :void)
  end

  @doc """
  List messages in a thread

  Returns a cursor-paginated list of messages belonging to the specified thread,
  ordered from oldest to newest. Supply `before_cursor`, `after_cursor`, or both
  to page through or bound the result set; omit both to receive the most recent page.
  Supply `anchor` and `direction` to fetch a window before, after, or around a
  specific message. Use `anchor=last_matching&anchor_agent_mode=embedded` to
  resolve the anchor from the latest embedded-agent message, and add
  `anchor_agent` to scope that resolution to a single sender agent.
  Supply `metadata` as a JSON-encoded structured expression to filter message
  metadata before cursor pagination or anchored window limits are applied.

  The authenticated user must have access to the thread's owner (workspace or user).
  A 403 is returned if the thread exists but is not accessible to the caller; a 404
  is returned if the thread does not exist or is not visible to the authenticated user.

  Pass `include_reply_counts: true` to annotate each message with the number of
  threaded replies it has received. This adds a small amount of latency and should
  be omitted when reply counts are not needed.


  Successful response
  """
  @spec messages(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadMessages.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadMessages.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def messages(
        client,
        thread,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadMessages.Params{}
      ) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/messages"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadMessages.Response}
    )
  end

  @doc """
  Update a thread's profile picture

  Uploads a new profile picture for the specified thread and returns the updated
  thread object. The image must be supplied as a base64-encoded string with its
  MIME type.

  The authenticated user must own the thread or be a team owner of the workspace
  the thread belongs to. Supplying invalid base64 data returns 422.


  The thread object after the profile picture has been updated.
  """
  @spec picture(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PutApiV1ThreadsThreadPicture.Input.t()
        ) :: {:ok, ArchAstro.SDK.Types.Thread.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def picture(client, thread, input) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/picture"

    ArchAstro.SDK.HTTP.request(client, :put, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.Thread}
    )
  end

  @doc """
  Retrieve a thread's read status

  Returns the read status of a thread for the specified user, including the ID
  of the last message they have read and the number of unread messages remaining.

  For user-authenticated requests, the status is always returned for the
  authenticated user and the `user` parameter is ignored. For server-to-server
  (S2S) requests, the `user` parameter is required and must be a valid user ID.

  Returns 404 if the thread does not exist or the caller does not have access
  to it.


  The read status record for the requested thread and user.
  """
  @spec read_status(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadReadStatus.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.ThreadReadStatus.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def read_status(
        client,
        thread,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadReadStatus.Params{}
      ) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/read_status"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.ThreadReadStatus}
    )
  end

  @doc """
  Search messages in a thread

  Searches canonical message content in the specified thread. `"text"` mode
  performs the existing case-insensitive substring search, `"embedding"` ranks
  stored message embeddings by cosine similarity, and `"hybrid"` combines the
  text and embedding rankings with Reciprocal Rank Fusion (RRF). Only messages
  visible to the authenticated caller are considered.

  Results are intentionally lean: each row contains only a bounded content
  snippet, sender identity, and timestamp. Attachments, reactions, ACLs, and
  metadata are neither hydrated nor serialized. At most 20 results are
  returned. Text results support chronological cursor pagination. Embedding and
  hybrid results are relevance-ranked single pages and return null cursors.


  Successful response
  """
  @spec search(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadSearch.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadSearch.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def search(client, thread, params) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/search"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadSearch.Response}
    )
  end

  @doc """
  List trajectories for a thread

  Returns a cursor-paginated list of thread message trajectories associated with the
  specified thread. Each trajectory links a user message and its agent response to the
  underlying AI trajectory record that captured the model's reasoning steps.

  The authenticated user must own the thread or be a member of the workspace it belongs
  to. Results are returned in reverse chronological order by default. Use `before_cursor`
  and `after_cursor` to navigate pages; provide at most one cursor per request.

  Optionally filter results to trajectories produced in response to a specific message
  by supplying the `message` parameter. When no trajectories match the query, `data`
  is an empty array and both cursor fields are `null`. A cursor that cannot be decoded
  returns a 400 `invalid_cursor` error.


  Successful response
  """
  @spec trajectories(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadTrajectories.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadTrajectories.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def trajectories(
        client,
        thread,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadTrajectories.Params{}
      ) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/trajectories"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadTrajectories.Response}
    )
  end
end

defmodule ArchAstro.SDK.V1.Threads.Members do
  @moduledoc """
  ThreadMember API resource.
  """

  @doc """
  Remove a member from a thread

  Removes a user or agent from the explicit roster of a private or restricted
  thread. Team-visible threads use implicit membership and reject individual
  removals. A member may remove themself; removing someone else requires
  permission to modify the thread. A successful removal returns HTTP 204 with
  no response body.

  Supply either `user` or `agent` depending on the value of `type`. Returns 404
  if the thread or the membership record does not exist.


  Empty response body. HTTP 204 on success.
  """
  @spec remove(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, :ok} | {:error, ArchAstro.SDK.Error.reason()}
  def remove(client, thread) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/members"
    ArchAstro.SDK.HTTP.request(client, :delete, path, decode: :void)
  end

  @doc """
  List members of a thread

  Returns all current user and agent members. Private and restricted threads
  return their explicit roster; team-visible threads return the owning team's
  implicit roster. The authenticated viewer must be able to see the thread.

  Results are returned as a flat array in the `data` field. The list is not
  paginated — all members are returned in a single response.


  Successful response
  """
  @spec list(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadMembers.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def list(client, thread) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/members"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadMembers.Response}
    )
  end

  @doc """
  Add a member to a thread

  Adds a user or agent to the explicit roster of a private or restricted
  thread. Team-visible threads use the owning team's implicit roster and reject
  explicit additions. On restricted threads, a team member may add themself;
  adding anyone else requires permission to modify the thread.

  Supply either `user` or `agent` depending on the value of `type`. Targets
  must be visible to the caller and, for an ordinary team-owned thread, must
  belong to the owning team. On success the membership record is returned with
  HTTP 201; repeated agent additions are idempotent.


  The user or agent membership that was added to the thread.
  """
  @spec create(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PostApiV1ThreadsThreadMembers.Input.t()
        ) :: {:ok, ArchAstro.SDK.Types.ChatMember.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def create(client, thread, input) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/members"

    ArchAstro.SDK.HTTP.request(client, :post, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.ChatMember}
    )
  end
end

defmodule ArchAstro.SDK.V1.Threads.Settings do
  @moduledoc """
  Setting API resource.
  """

  @doc """
  Retrieve thread settings

  Returns the current settings for the specified thread. Settings control
  per-thread behavior such as whether the AI agent is enabled.

  The authenticated user must own the thread or be a member of its workspace.
  If settings have never been explicitly configured, defaults are returned
  (for example, `agent_enabled` defaults to `true`).


  Successful response
  """
  @spec list(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadSettings.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def list(client, thread) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/settings"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1ThreadsThreadSettings.Response}
    )
  end

  @doc """
  Update thread settings

  Updates the settings for the specified thread. Only fields included in
  the `settings` map are modified; omitted fields retain their current values.

  The authenticated user must own the thread or be a member of its workspace.
  Returns the full settings object reflecting the state after the update.
  Validation errors are returned as `422 Unprocessable Entity`.


  The thread settings object after the update has been applied.
  """
  @spec replace(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PutApiV1ThreadsThreadSettings.Input.t()
        ) :: {:ok, ArchAstro.SDK.Types.ThreadSettings.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def replace(client, thread, input) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/settings"

    ArchAstro.SDK.HTTP.request(client, :put, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.ThreadSettings}
    )
  end
end

defmodule ArchAstro.SDK.V1.Threads.Tags do
  @moduledoc """
  Tag API resource.
  """

  @doc """
  Remove tags from a thread

  Removes one or more status tags from the thread and returns the updated
  thread. Removing a tag the thread does not have is a no-op.

  Any participant of the thread — a human member or an agent member — may edit
  tags. Supply the tags to remove as repeated query parameters, e.g.
  `?tags[]=blocked&tags[]=needs-review`.


  The thread object after the tags were removed.
  """
  @spec remove(ArchAstro.SDK.Client.t(), String.t()) ::
          {:ok, ArchAstro.SDK.Types.Thread.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def remove(client, thread) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/tags"
    ArchAstro.SDK.HTTP.request(client, :delete, path, decode: {:ref, ArchAstro.SDK.Types.Thread})
  end

  @doc """
  Add tags to a thread

  Adds one or more status tags to the thread and returns the updated thread.

  Any participant of the thread — a human member or an agent member — may edit
  tags; this is broader than the owner/admin permission required to update other
  thread fields. Adding a tag the thread already has is a no-op. Tags are
  normalized (trimmed and lowercased) and may contain only lowercase letters,
  numbers, hyphens, and underscores.


  The thread object after the tags were added.
  """
  @spec create(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PostApiV1ThreadsThreadTags.Input.t()
        ) :: {:ok, ArchAstro.SDK.Types.Thread.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def create(client, thread, input) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/tags"

    ArchAstro.SDK.HTTP.request(client, :post, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.Thread}
    )
  end

  @doc """
  Replace a thread's tags

  Replaces the thread's entire set of status tags with the provided list and
  returns the updated thread. Passing an empty array clears all tags.

  Any participant of the thread — a human member or an agent member — may edit
  tags. Tags are normalized (trimmed and lowercased) and may contain only
  lowercase letters, numbers, hyphens, and underscores.


  The thread object after its tags were replaced.
  """
  @spec replace(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.PutApiV1ThreadsThreadTags.Input.t()
        ) :: {:ok, ArchAstro.SDK.Types.Thread.t()} | {:error, ArchAstro.SDK.Error.reason()}
  def replace(client, thread, input) do
    path = "/api/v1/threads/#{ArchAstro.SDK.Path.encode(thread)}/tags"

    ArchAstro.SDK.HTTP.request(client, :put, path,
      body: input,
      decode: {:ref, ArchAstro.SDK.Types.Thread}
    )
  end
end
